structure:
CREATE TABLE table_name (
  column_name data_type [constraints]
);

ALTER TABLE table_name
ADD COLUMN column_name data_type;

DROP TABLE table_name;

example:
CREATE TABLE customer_note (
  note_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  customer_id smallint NOT NULL REFERENCES customer(customer_id),
  note_text text NOT NULL
);

ALTER TABLE customer_note
ADD COLUMN created_at timestamptz NOT NULL DEFAULT now();

DROP TABLE customer_note;

structure:
INSERT INTO table_name (column1)
VALUES (value1);

UPDATE table_name
SET column1 = value1
WHERE condition;

DELETE FROM table_name
WHERE condition;

CREATE VIEW view_name AS
SELECT columns
FROM table_name;

SELECT columns
FROM view_name;

DROP VIEW view_name;

CREATE TEMPORARY TABLE temp_table AS
SELECT columns
FROM source_table
WHERE condition;

SELECT aggregate_function(column_name)
FROM temp_table;

CREATE PROCEDURE procedure_name(parameter_name data_type)
BEGIN
  -- statements
END;

CALL procedure_name(argument_value);

example:
CREATE PROCEDURE validate_customer(p_customer_id smallint)
LANGUAGE plpgsql
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM customer
    WHERE customer_id = p_customer_id
  ) THEN
    RAISE EXCEPTION 'Customer % does not exist', p_customer_id;
  END IF;
END;
$$;

CALL validate_customer(1);

DROP PROCEDURE validate_customer(smallint);

CREATE FUNCTION set_customer_last_update()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.last_update := now();
  RETURN NEW;
END;
$$;

CREATE TRIGGER customer_set_last_update
BEFORE UPDATE ON customer
FOR EACH ROW
EXECUTE FUNCTION set_customer_last_update();

DROP TRIGGER customer_set_last_update ON customer;

DROP FUNCTION set_customer_last_update();

