CREATE INDEX index_name
ON table_name (column1 [, column2]);

SELECT columns
FROM table_name
WHERE column1 = value;

DROP INDEX index_name;

example:
CREATE INDEX idx_payment_customer_date
ON payment (customer_id, payment_date);

SELECT
  payment_id,
  amount
FROM payment
WHERE customer_id = 1
  AND payment_date >= timestamp '2005-06-01';

DROP INDEX idx_payment_customer_date;

